    int ss = static_cast<int>(s.size());
    int ts = static_cast<int>(t.size());
    int total_masks = 1 << ss;

    vector<int> num(ts, 0), cnt(total_masks, 0);
    vector<vector<ll>> dp(ts + 1, vector<ll>(total_masks, 0));

    for (int i = 0; i < ss; ++i) {
        for (int j = 0; j < ts; ++j) {
            if (t[j] % s[i] == 0) {
                num[j] |= (1 << i);
            }
        }
    }

    for (int mask = 0; mask < total_masks; ++mask) {
        for (int j = 0; j < ts; ++j) {
            if ((num[j] & mask) == num[j]) {
                ++cnt[mask];
            }
        }
    }

    for (int i = 0; i < ts; ++i) {
        ++dp[1][num[i]];
    }

    for (int k = 1; k < ts; ++k) {
        for (int mask = 0; mask < total_masks; ++mask) {
