                    dp[k + 1][mask | num[i]] += dp[k][mask];
                    dp[k + 1][mask | num[i]] %= MOD;
                }
            }

            ll ways = (cnt[mask] - k + MOD) % MOD;
            dp[k + 1][mask] =
                (dp[k + 1][mask] + dp[k][mask] * ways) % MOD;
        }
    }

    return dp[ts][total_masks - 1];
}

