int ans = 1, cur= 0;
bool mark[MAXN];
int calc_cnt(){

	int ss = s.size(), ts = t.size();
	vector<int>num(ts, 0), cnt(1 << ss, 0);
	vector<vector<int>>dp(ts + 1, vector<int>(1 << ss, 0);
	for(int i = 0; i < ss; i ++)
		for(int j = 0; j < ts; j ++)
			if(t[j] % s[i] == 0)
				num[j] |= (1 << i);
	for(int i = 0; i < (1 << ss); i ++)
		for(int j = 0; j < ts; j ++)
			if((num[j] & i) == num[j])
				cnt[i] ++;
	for(int i = 0; i < ts; i ++)
		dp[1][num[i]] ++;
	for(int k = 1; k < ts; k ++){
		for(int mask = 0; mask < (1 << ss); mask ++){
			dp[k][mask] %= MOD;
			for(int i = 0; i < ts; i ++){
				int ands = (num[i] & mask); 	
				if(ands != num[i] && ands != 0){
					dp[k + 1][mask | num[i]] %= MOD;
					dp[k + 1][mask | num[i]] += dp[k][mask];
					dp[k + 1][mask | num[i]] %= MOD;
				}
			}
			dp[k + 1][mask] = ((dp[k + 1][mask]% MOD) + (1ll * (dp[k][mask] % MOD * ((cnt[mask] - k) % MOD)) % MOD) % MOD);
		}
	}	
	return dp[ts][(1 << ss) - 1];
}

void dfs(int v){
    mark[v] = 1;
    if(indeg[v] == 0){
        s.pb(a[v]);
    }else{
    	t.pb(a[v]);
    }
    for(auto u : adj[v]){
        if(!mark[u]){
            dfs(u);
        }
    }
    return;
}
void dfs_all(){
    for(int i = 0; i < n; i ++){
        if(!mark[i]){
        	s.clear(), t.clear();
            dfs(i);
            if(!t.empty()){
				int cnt = calc_cnt(), tt = t.size() - 1;
				ans = 1ll * (ans%MOD) * (cnt % MOD) % MOD;
				ans = 1ll * (ans % MOD) * (c[cur + tt][tt] % MOD) % MOD;
				cur += tt;
			}
        }
    }
    return;
}
