    fastio;
    for(int i = 0; i < MAXN; i ++){
    	c[i][0]  = 1;
    	for(int j = 1; j <= i; j ++){
    		c[i][j] = (c[i - 1][j - 1] + c[i - 1][j])%MOD;
    	}
    }
    cin >> n;
    for(int i = 0; i < n; i ++){
        cin >> a[i];
    }
    sort(a, a + n);
    for(int i = 0; i < n; i ++){
        for(int j = 0; j < n; j ++)if(i != j){
            if(a[j] % a[i] == 0){
                adj[j].pb(i);
                adj[i].pb(j);
                indeg[j] ++;
            }
        }
    }

    dfs_all();
	cout << ans % MOD << endl;
    return 0;

}
